import { initDatabase, getDatabase } from '../src/db/database';

/**
 * Explicit cleanup script for confirmed test-generated artifacts in sidequest.db.
 * Only removes records generated by automated test runs (matching test patterns),
 * preserving any legitimate user accounts or missions.
 */
function cleanTestData() {
  initDatabase();
  const db = getDatabase();

  console.log('Cleaning test-generated records from sidequest.db...');

  // 1. Delete teams created by test users (cascades to memberships, invitations)
  const testUsers = db.prepare(`
    SELECT id FROM users 
    WHERE email LIKE '%@threadback.test' 
       OR email LIKE 'test-%@example.com'
  `).all() as { id: string }[];
  const testUserIds = testUsers.map(u => u.id);

  if (testUserIds.length > 0) {
    const placeholders = testUserIds.map(() => '?').join(',');
    db.prepare(`DELETE FROM team_invitations WHERE invited_by IN (${placeholders})`).run(...testUserIds);
    db.prepare(`DELETE FROM team_memberships WHERE user_id IN (${placeholders})`).run(...testUserIds);
    db.prepare(`DELETE FROM teams WHERE created_by IN (${placeholders})`).run(...testUserIds);
    db.prepare(`DELETE FROM users WHERE id IN (${placeholders})`).run(...testUserIds);
  }
  console.log(`Cleaned ${testUserIds.length} test users and their teams/invitations.`);

  // Clean unassigned auto-generated legacy test missions
  const deleteTestMissions = db.prepare(`
    DELETE FROM missions 
    WHERE objective = 'Build a Go CRUD API' 
       OR objective = 'Test mission'
       OR objective LIKE 'Build a high-performance HTTP gateway%'
       OR objective = 'Alice Private Salary Notes'
       OR objective = 'Implement OAuth2 and Team Workspaces'
  `);
  const missionResult = deleteTestMissions.run();
  console.log(`Removed ${missionResult.changes} test/seed missions.`);

  console.log('Cleanup complete.');
}

cleanTestData();
